const scenes=[{name:'The stolen song',art:'chapter-1-2.webp',film:'chapter-01.mp4'},{name:'The undercity well',art:'chapter-3-1.webp',film:'chapter-03.mp4'},{name:'The sky engine',art:'chapter-6-1.webp',film:'chapter-06.mp4'},{name:'Orchard after fire',art:'chapter-7-1.webp',film:'chapter-07.mp4'}];
const art=document.querySelector('#scene-art'),buttons=[...document.querySelectorAll('[data-scene]')],dialog=document.querySelector('#theatre'),film=document.querySelector('#film'),score=document.querySelector('#score'),sound=document.querySelector('#sound');let index=0,soundOn=false,manualUntil=0;
function select(n){index=(n+scenes.length)%scenes.length;art.src='game/cinema/expanded/art/'+scenes[index].art;art.alt=scenes[index].name;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',i===index));document.querySelector('#scene-count').textContent=String(index+1).padStart(2,'0')+' / 04';}
buttons.forEach((b,i)=>b.onclick=()=>{manualUntil=Date.now()+22000;select(i)});
setInterval(()=>{if(!document.hidden&&!dialog.open&&Date.now()>manualUntil&&!matchMedia('(prefers-reduced-motion: reduce)').matches)select(index+1)},10000);
sound.onclick=async()=>{if(soundOn){score.pause();soundOn=false}else{score.volume=.35;try{await score.play();soundOn=true}catch(e){sound.textContent='Tap to retry sound';return}}sound.textContent=soundOn?'Sound on':'Sound off';sound.setAttribute('aria-pressed',soundOn)};
function loadFilm(){const s=scenes[index];document.querySelector('#film-title').textContent=s.name;document.querySelector('#film-count').textContent=String(index+1).padStart(2,'0')+' / 04';film.poster='game/cinema/expanded/art/'+s.art;film.src='game/cinema/arrivals/'+s.film;film.play().catch(()=>{});}
document.querySelector('#watch').onclick=()=>{score.pause();dialog.showModal();loadFilm()};document.querySelector('#close-film').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{film.pause();film.removeAttribute('src');film.load();if(soundOn)score.play().catch(()=>{})});document.querySelector('#previous').onclick=()=>{select(index-1);loadFilm()};document.querySelector('#next').onclick=()=>{select(index+1);loadFilm()};film.addEventListener('ended',()=>{select(index+1);loadFilm()});document.addEventListener('visibilitychange',()=>{if(document.hidden){score.pause();film.pause()}else if(soundOn&&!dialog.open)score.play().catch(()=>{})});
